            if p_min_r <= pr <= p_max_r and p_min_c <= pc <= p_max_c:
                pattern_img[pr - p_min_r][pc - p_min_c] = color

        # Compute scale: pattern area → interior area
        # If pattern is small (2 pixels), scale up significantly
        # If pattern matches interior size, 1:1

        scale_factor = max(1, int(max(int_h, int_w)) // max(pattern_h, pattern_w)) if pattern_h > 0 and pattern_w > 0 else 1

        # Center placement
        pos_r = (int_h - pattern_h * scale_factor) // 2 + 1
        pos_c = (int_w - pattern_w * scale_factor) // 2 + 1

        # Paint scaled pattern
        for r in range(pattern_h):
            for c in range(pattern_w):
                if pattern_img[r][c] != 0:
                    tr = pos_r + r * scale_factor
                    tc = pos_c + c * scale_factor
                    if 0 < tr < out_h and 0 < tc < out_w:
                        result[tr][tc] = pattern_img[r][c]

    return result
